const AUCTION='0x2943Fd3DD84BB3Bf51d5C4b288f648ab45e4Fc3D';
const TOKEN='0x1A339C38Ae22726F1A4235bCecf8f12aebE4C5E8';
const url=new URL('https://base.blockscout.com/api');
url.searchParams.set('module','account');url.searchParams.set('action','tokentx');url.searchParams.set('address',AUCTION);
url.searchParams.set('contractaddress',TOKEN);url.searchParams.set('startblock','49285487');
url.searchParams.set('page','1');url.searchParams.set('offset','1000');url.searchParams.set('sort','asc');
const response=await fetch(url,{headers:{accept:'application/json','user-agent':'warplet-bid-audit'},signal:AbortSignal.timeout(30000)});
const text=await response.text();let body;try{body=JSON.parse(text)}catch{body={raw:text}};
const rows=Array.isArray(body?.result)?body.result:[];
console.log(JSON.stringify({fetchedAt:new Date().toISOString(),status:response.status,auction:AUCTION,token:TOKEN,startBlock:49285487,count:rows.length,rows},null,2));
